{"command":"cat <<'EOF' > go.mod
module reimplemented/errcheck

go 1.21
EOF
cat <<'EOF' > main.go
package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type tagFlag []string

func (t *tagFlag) String() string { return strings.Join(*t, " ") }
func (t *tagFlag) Set(s string) error {
	for _, f := range strings.FieldsFunc(s, func(r rune) bool { return r == ',' || r == ' ' || r == '\t' || r == '\n' }) {
		if f != "" {
			*t = append(*t, f)
		}
	}
	return nil
}

type ignoreFlag struct {
	raw map[string]string
	re  map[string]*regexp.Regexp
}

func (i *ignoreFlag) String() string { return "" }
func (i *ignoreFlag) Set(s string) error {
	if i.raw == nil {
		i.raw = make(map[string]string)
		i.re = make(map[string]*regexp.Regexp)
	}
	parts := strings.Split(s, ",")
	for _, p := range parts {
		pkg := ""
		rx := p
		if idx := strings.Index(p, ":"); idx >= 0 {
			pkg = p[:idx]
			rx = p[idx+1:]
		}
		r, err := regexp.Compile(rx)
		if err != nil {
			return err
		}
		i.raw[pkg] = rx
		i.re[pkg] = r
	}
	return nil
}

type config struct {
	abspath         bool
	asserts         bool
	blank           bool
	excludeFile     string
	excludeOnly     bool
	ignoreGenerated bool
	ignoreTests     bool
	mod             string
	verbose         bool
	tags            tagFlag
	ignores         ignoreFlag
	ignorePkgs      map[string]bool
	excludes        []excludeRule
	cwd             string
}

type excludeRule struct {
	name     string
	argType  string
	original string
}

type packageInfo struct {
	Dir          string
	ImportPath   string
	Name         string
	GoFiles      []string
	CgoFiles     []string
	TestGoFiles  []string
	XTestGoFiles []string
	Imports      []string
	ImportMap    map[string]string
	Error        *packageError
	Incomplete   bool
	Standard     bool
}

type packageError struct {
	Err string
	Pos string
}

type sourceFile struct {
	abs       string
	lines     []string
	generated bool
}

type analyzer struct {
	cfg          *config
	fset         *token.FileSet
	files        map[string]*sourceFile
	findings     []finding
	currentInfo  *types.Info
	currentPkg   *types.Package
	errorIface   *types.Interface
	sourceImport *sourceImporter
}

type finding struct {
	absFile string
	file    string
	line    int
	col     int
	text    string
	name    string
}

type callMeta struct {
	name       string
	pkgPath    string
	fullName   string
	verbose    string
	firstArg   ast.Expr
	firstType  types.Type
	recvType   types.Type
	isSelector bool
}

func main() {
	cfg, args, ok := parseFlags(os.Args)
	if !ok {
		os.Exit(2)
	}
	cwd, err := os.Getwd()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(2)
	}
	cfg.cwd = cwd
	if cfg.ignorePkgs == nil {
		cfg.ignorePkgs = make(map[string]bool)
	}

	if cfg.excludeFile != "" {
		rules, err := readExcludeFile(cfg.excludeFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Could not read exclude file: %v\n", err)
			os.Exit(2)
		}
		cfg.excludes = append(cfg.excludes, rules...)
	}
	if !cfg.excludeOnly {
		cfg.excludes = append(defaultExcludeRules(), cfg.excludes...)
	}

	if len(args) == 0 {
		args = []string{"."}
	}

	fset := token.NewFileSet()
	imp := newSourceImporter(cfg, fset)
	an := &analyzer{
		cfg:          cfg,
		fset:         fset,
		files:        make(map[string]*sourceFile),
		errorIface:   types.Universe.Lookup("error").Type().Underlying().(*types.Interface).Complete(),
		sourceImport: imp,
	}
	imp.an = an

	var runErr error
	if hasGoFileArg(args) {
		for _, a := range args {
			if !strings.HasSuffix(a, ".go") {
				runErr = fmt.Errorf("-: named files must be .go files: %s", a)
				break
			}
		}
		if runErr == nil {
			runErr = an.analyzeFileArgs(args)
		}
	} else {
		runErr = an.analyzePatterns(args)
	}

	if runErr != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", runErr)
		os.Exit(2)
	}

	findings := dedupFindings(an.findings)
	sort.Slice(findings, func(i, j int) bool {
		a, b := findings[i], findings[j]
		if a.file != b.file {
			return a.file < b.file
		}
		if a.line != b.line {
			return a.line < b.line
		}
		if a.col != b.col {
			return a.col < b.col
		}
		if a.name != b.name {
			return a.name < b.name
		}
		return a.text < b.text
	})
	for _, f := range findings {
		if cfg.verbose && f.name != "" {
			fmt.Printf("%s:%d:%d:\t%s\t%s\n", f.file, f.line, f.col, f.name, f.text)
		} else {
			fmt.Printf("%s:%d:%d:\t%s\n", f.file, f.line, f.col, f.text)
		}
	}
	if len(findings) > 0 {
		os.Exit(1)
	}
}

func parseFlags(argv []string) (*config, []string, bool) {
	cfg := &config{}
	fs := flag.NewFlagSet(argv[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.BoolVar(&cfg.abspath, "abspath", false, "print absolute paths to files")
	fs.BoolVar(&cfg.asserts, "asserts", false, "if true, check for ignored type assertion results")
	fs.BoolVar(&cfg.blank, "blank", false, "if true, check for errors assigned to blank identifier")
	fs.StringVar(&cfg.excludeFile, "exclude", "", "Path to a file containing a list of functions to exclude from checking")
	fs.BoolVar(&cfg.excludeOnly, "excludeonly", false, "Use only excludes from -exclude file")
	fs.Var(&cfg.ignores, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	fs.BoolVar(&cfg.ignoreGenerated, "ignoregenerated", false, "if true, checking of files with generated code is disabled")
	var ignorePkg string
	fs.StringVar(&ignorePkg, "ignorepkg", "", "comma-separated list of package paths to ignore")
	fs.BoolVar(&cfg.ignoreTests, "ignoretests", false, "if true, checking of _test.go files is disabled")
	fs.StringVar(&cfg.mod, "mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
	fs.Var(&cfg.tags, "tags", "comma or space-separated list of build tags to include")
	fs.BoolVar(&cfg.verbose, "verbose", false, "produce more verbose logging")
	if err := fs.Parse(argv[1:]); err != nil {
		return nil, nil, false
	}
	cfg.ignorePkgs = make(map[string]bool)
	if ignorePkg != "" {
		for _, p := range strings.Split(ignorePkg, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				cfg.ignorePkgs[p] = true
			}
		}
	}
	return cfg, fs.Args(), true
}

func hasGoFileArg(args []string) bool {
	for _, a := range args {
		if strings.HasSuffix(a, ".go") {
			return true
		}
	}
	return false
}

func readExcludeFile(path string) ([]excludeRule, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var out []excludeRule
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		out = append(out, parseExcludeRule(line))
	}
	return out, nil
}

func parseExcludeRule(s string) excludeRule {
	r := excludeRule{name: s, original: s}
	if strings.HasPrefix(s, "(") {
		if idx := strings.LastIndex(s, ")."); idx >= 0 {
			prefix := s[:idx+2]
			rest := s[idx+2:]
			if j := strings.Index(rest, "("); j >= 0 && strings.HasSuffix(rest, ")") {
				r.name = prefix + rest[:j]
				r.argType = rest[j+1 : len(rest)-1]
			}
		}
		return r
	}
	if i := strings.Index(s, "("); i >= 0 && strings.HasSuffix(s, ")") {
		r.name = s[:i]
		r.argType = s[i+1 : len(s)-1]
	}
	return r
}

func defaultExcludeRules() []excludeRule {
	names := []string{
		"fmt.Print", "fmt.Printf", "fmt.Println",
		"(*bytes.Buffer).Write", "(*bytes.Buffer).WriteByte", "(*bytes.Buffer).WriteRune", "(*bytes.Buffer).WriteString",
		"(*strings.Builder).Write", "(*strings.Builder).WriteByte", "(*strings.Builder).WriteRune", "(*strings.Builder).WriteString",
		"math/rand.Read", "(*math/rand.Rand).Read",
	}
	out := make([]excludeRule, 0, len(names))
	for _, n := range names {
		out = append(out, excludeRule{name: n, original: n})
	}
	return out
}

func (an *analyzer) analyzeFileArgs(args []string) error {
	files, err := an.parseFileList(args)
	if err != nil {
		return err
	}
	if len(files) == 0 {
		return nil
	}
	if an.cfg.verbose {
		fmt.Fprintln(os.Stderr, "checking command-line-arguments")
	}
	_, info, err := an.typecheck("command-line-arguments", files, nil)
	if err != nil {
		return err
	}
	an.currentInfo = info
	an.currentPkg = nil
	for _, f := range files {
		an.analyzeAST(f)
	}
	return nil
}

func (an *analyzer) analyzePatterns(patterns []string) error {
	pkgs, err := an.sourceImport.loadPackages(patterns)
	if err != nil {
		return err
	}
	for _, p := range pkgs {
		if p.Error != nil {
			return fmt.Errorf("errors while loading package %s: [-: %s]", p.ImportPath, p.Error.Err)
		}
		if p.ImportPath == "" || p.Dir == "" {
			continue
		}
		an.sourceImport.data[p.ImportPath] = p
	}
	for _, p := range pkgs {
		if p.Error != nil || p.Dir == "" {
			continue
		}
		if err := an.analyzeListedPackage(p); err != nil {
			return err
		}
	}
	return nil
}

func (an *analyzer) analyzeListedPackage(p *packageInfo) error {
	baseNames := append([]string{}, p.GoFiles...)
	baseNames = append(baseNames, p.CgoFiles...)
	if !an.cfg.ignoreTests {
		baseNames = append(baseNames, p.TestGoFiles...)
	}
	basePaths := absFiles(p.Dir, baseNames)
	if len(basePaths) > 0 {
		files, err := an.parseFileList(basePaths)
		if err != nil {
			return err
		}
		if an.cfg.verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", p.ImportPath)
		}
		pkg, info, err := an.typecheck(p.ImportPath, files, p.ImportMap)
		if err != nil {
			return err
		}
		an.sourceImport.cache[p.ImportPath] = pkg
		an.currentInfo = info
		an.currentPkg = pkg
		for _, f := range files {
			an.analyzeAST(f)
		}
	}
	if !an.cfg.ignoreTests && len(p.XTestGoFiles) > 0 {
		xpaths := absFiles(p.Dir, p.XTestGoFiles)
		files, err := an.parseFileList(xpaths)
		if err != nil {
			return err
		}
		xpath := p.ImportPath + "_test"
		if an.cfg.verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", xpath)
		}
		pkg, info, err := an.typecheck(xpath, files, p.ImportMap)
		if err != nil {
			return err
		}
		an.currentInfo = info
		an.currentPkg = pkg
		for _, f := range files {
			an.analyzeAST(f)
		}
	}
	return nil
}

func absFiles(dir string, names []string) []string {
	var out []string
	for _, n := range names {
		if n == "" || !strings.HasSuffix(n, ".go") {
			continue
		}
		if filepath.IsAbs(n) {
			out = append(out, filepath.Clean(n))
		} else {
			out = append(out, filepath.Join(dir, n))
		}
	}
	return out
}

func (an *analyzer) parseFileList(paths []string) ([]*ast.File, error) {
	var files []*ast.File
	for _, p := range paths {
		abs, err := filepath.Abs(p)
		if err != nil {
			return nil, err
		}
		abs = filepath.Clean(abs)
		data, err := os.ReadFile(abs)
		if err != nil {
			return nil, err
		}
		an.files[abs] = &sourceFile{abs: abs, lines: splitLines(data), generated: isGenerated(data)}
		f, err := parser.ParseFile(an.fset, abs, data, parser.ParseComments)
		if err != nil {
			return nil, err
		}
		files = append(files, f)
	}
	return files, nil
}

func splitLines(data []byte) []string {
	data = bytes.ReplaceAll(data, []byte("\r\n"), []byte("\n"))
	return strings.Split(string(data), "\n")
}

func isGenerated(data []byte) bool {
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "// Code generated ") && strings.Contains(line, " DO NOT EDIT.") {
			return true
		}
	}
	return false
}

func (an *analyzer) typecheck(path string, files []*ast.File, importMap map[string]string) (*types.Package, *types.Info, error) {
	info := &types.Info{
		Types:      make(map[ast.Expr]types.TypeAndValue),
		Defs:       make(map[*ast.Ident]types.Object),
		Uses:       make(map[*ast.Ident]types.Object),
		Selections: make(map[*ast.SelectorExpr]*types.Selection),
	}
	var errs []error
	conf := types.Config{
		Importer: &mappedImporter{base: an.sourceImport, importMap: importMap},
		Error: func(err error) {
			errs = append(errs, err)
		},
	}
	pkg, err := conf.Check(path, an.fset, files, info)
	if err != nil || len(errs) > 0 {
		if len(errs) > 0 {
			return pkg, info, joinErrors(errs)
		}
		return pkg, info, err
	}
	return pkg, info, nil
}

func joinErrors(errs []error) error {
	if len(errs) == 0 {
		return nil
	}
	parts := make([]string, len(errs))
	for i, e := range errs {
		parts[i] = e.Error()
	}
	return errors.New(strings.Join(parts, "\n"))
}

type mappedImporter struct {
	base      *sourceImporter
	importMap map[string]string
}

func (m *mappedImporter) Import(path string) (*types.Package, error) {
	return m.ImportFrom(path, "", 0)
}
func (m *mappedImporter) ImportFrom(path, dir string, mode types.ImportMode) (*types.Package, error) {
	if m.importMap != nil {
		if actual := m.importMap[path]; actual != "" {
			path = actual
		}
	}
	return m.base.ImportFrom(path, dir, mode)
}

type sourceImporter struct {
	cfg     *config
	fset    *token.FileSet
	an      *analyzer
	def     types.ImporterFrom
	cache   map[string]*types.Package
	data    map[string]*packageInfo
	loading map[string]bool
}

func newSourceImporter(cfg *config, fset *token.FileSet) *sourceImporter {
	var imp types.ImporterFrom
	if d, ok := importer.Default().(types.ImporterFrom); ok {
		imp = d
	}
	return &sourceImporter{cfg: cfg, fset: fset, def: imp, cache: make(map[string]*types.Package), data: make(map[string]*packageInfo), loading: make(map[string]bool)}
}

func (s *sourceImporter) Import(path string) (*types.Package, error) { return s.ImportFrom(path, "", 0) }
func (s *sourceImporter) ImportFrom(path, dir string, mode types.ImportMode) (*types.Package, error) {
	if p := s.cache[path]; p != nil {
		return p, nil
	}
	// Prefer compiled export data when available. This keeps standard library imports fast
	// and handles the compiler's internal packages accurately.
	if s.def != nil {
		if p, err := s.def.ImportFrom(path, dir, mode); err == nil {
			s.cache[path] = p
			return p, nil
		}
	} else {
		if p, err := importer.Default().Import(path); err == nil {
			s.cache[path] = p
			return p, nil
		}
	}
	if s.loading[path] {
		return nil, fmt.Errorf("import cycle involving %s", path)
	}
	pinfo := s.data[path]
	if pinfo == nil {
		list, err := s.loadPackages([]string{path})
		if err != nil {
			return nil, err
		}
		for _, p := range list {
			s.data[p.ImportPath] = p
			if p.ImportPath == path {
				pinfo = p
			}
		}
	}
	if pinfo == nil || pinfo.Error != nil || pinfo.Dir == "" {
		if pinfo != nil && pinfo.Error != nil {
			return nil, errors.New(pinfo.Error.Err)
		}
		return nil, fmt.Errorf("can't find import: %s", path)
	}
	s.loading[path] = true
	defer delete(s.loading, path)
	paths := absFiles(pinfo.Dir, append(append([]string{}, pinfo.GoFiles...), pinfo.CgoFiles...))
	files, err := s.an.parseFileList(paths)
	if err != nil {
		return nil, err
	}
	pkg, _, err := s.an.typecheck(path, files, pinfo.ImportMap)
	if err != nil {
		return nil, err
	}
	s.cache[path] = pkg
	return pkg, nil
}

func (s *sourceImporter) loadPackages(patterns []string) ([]*packageInfo, error) {
	args := []string{"list", "-e", "-json"}
	if s.cfg.mod != "" {
		args = append(args, "-mod="+s.cfg.mod)
	}
	if len(s.cfg.tags) > 0 {
		args = append(args, "-tags", strings.Join(s.cfg.tags, ","))
	}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	cmd.Dir = s.cfg.cwd
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {
		serr := stderr.String()
		if strings.Contains(serr, "go.mod file not found") {
			return nil, nil
		}
		return nil, fmt.Errorf("err: %v: stderr: %s", err, serr)
	}
	dec := json.NewDecoder(&stdout)
	var out []*packageInfo
	for {
		var p packageInfo
		if err := dec.Decode(&p); err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return nil, err
		}
		out = append(out, &p)
	}
	return out, nil
}

func (an *analyzer) analyzeAST(f *ast.File) {
	abs := filepath.Clean(an.fset.Position(f.Pos()).Filename)
	if an.cfg.ignoreGenerated {
		if sf := an.files[abs]; sf != nil && sf.generated {
			return
		}
	}
	checkedAssertions := make(map[*ast.TypeAssertExpr]bool)
	ast.Inspect(f, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.AssignStmt:
			an.markCheckedAssertionsAssign(n.Lhs, n.Rhs, checkedAssertions)
			an.checkAssignmentLike(n.Lhs, n.Rhs)
			an.checkAssertionAssignmentQuirk(n.Lhs, n.Rhs)
		case *ast.ValueSpec:
			lhs := make([]ast.Expr, len(n.Names))
			for i := range n.Names { lhs[i] = n.Names[i] }
			an.markCheckedAssertionsAssign(lhs, n.Values, checkedAssertions)
			an.checkAssignmentLike(lhs, n.Values)
			an.checkAssertionAssignmentQuirk(lhs, n.Values)
		}
		return true
	})
	ast.Inspect(f, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.ExprStmt:
			if c, ok := n.X.(*ast.CallExpr); ok {
				an.checkIgnoredCall(c)
			}
		case *ast.GoStmt:
			an.checkIgnoredCall(n.Call)
		case *ast.DeferStmt:
			an.checkIgnoredCall(n.Call)
		case *ast.TypeAssertExpr:
			if an.cfg.asserts && n.Type != nil && !checkedAssertions[n] {
				an.addFinding(n.X.Pos(), "")
			}
		}
		return true
	})
}

func (an *analyzer) markCheckedAssertionsAssign(lhs []ast.Expr, rhs []ast.Expr, checked map[*ast.TypeAssertExpr]bool) {
	if !an.cfg.asserts || len(lhs) != 2 || len(rhs) != 1 {
		return
	}
	if ta, ok := rhs[0].(*ast.TypeAssertExpr); ok && ta.Type != nil {
		checked[ta] = true
		if an.cfg.blank {
			if id, ok := lhs[1].(*ast.Ident); ok && id.Name == "_" {
				an.addFinding(id.Pos(), "")
			}
		}
	}
}

func (an *analyzer) checkAssertionAssignmentQuirk(lhs []ast.Expr, rhs []ast.Expr) {
	if !an.cfg.asserts || len(rhs) <= 1 {
		return
	}
	for i, r := range rhs {
		if i >= len(lhs) {
			break
		}
		if ta, ok := r.(*ast.TypeAssertExpr); ok && ta.Type != nil {
			an.addFinding(lhs[i].Pos(), "")
		}
	}
}

func (an *analyzer) checkIgnoredCall(c *ast.CallExpr) {
	if !an.callHasError(c) {
		return
	}
	meta := an.callMeta(c)
	if an.shouldIgnore(meta) {
		return
	}
	an.addFinding(c.Lparen, meta.verbose)
}

func (an *analyzer) checkAssignmentLike(lhs []ast.Expr, rhs []ast.Expr) {
	if !an.cfg.blank || len(lhs) == 0 || len(rhs) == 0 {
		return
	}
	if len(rhs) == 1 {
		if c, ok := rhs[0].(*ast.CallExpr); ok {
			meta := an.callMeta(c)
			if an.shouldIgnore(meta) {
				return
			}
			res := an.callResultTypes(c)
			for i, t := range res {
				if i < len(lhs) && isBlank(lhs[i]) && an.isError(t) {
					an.addFinding(lhs[i].Pos(), meta.verbose)
				}
			}
		}
		return
	}
	for i, r := range rhs {
		if i >= len(lhs) || !isBlank(lhs[i]) {
			continue
		}
		c, ok := r.(*ast.CallExpr)
		if !ok {
			continue
		}
		meta := an.callMeta(c)
		if an.shouldIgnore(meta) {
			continue
		}
		res := an.callResultTypes(c)
		if len(res) > 0 && an.isError(res[0]) {
			an.addFinding(lhs[i].Pos(), meta.verbose)
		}
	}
}

func isBlank(e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	return ok && id.Name == "_"
}

func (an *analyzer) callHasError(c *ast.CallExpr) bool {
	for _, t := range an.callResultTypes(c) {
		if an.isError(t) {
			return true
		}
	}
	return false
}

func (an *analyzer) callResultTypes(c *ast.CallExpr) []types.Type {
	tv, ok := an.currentInfo.Types[c]
	if !ok || tv.Type == nil {
		return nil
	}
	t := tv.Type
	if tup, ok := t.(*types.Tuple); ok {
		out := make([]types.Type, tup.Len())
		for i := 0; i < tup.Len(); i++ {
			out[i] = tup.At(i).Type()
		}
		return out
	}
	return []types.Type{t}
}

func (an *analyzer) isError(t types.Type) bool {
	if t == nil {
		return false
	}
	if b, ok := t.(*types.Basic); ok && b.Info()&types.IsUntyped != 0 {
		t = types.Default(t)
	}
	return types.Implements(t, an.errorIface)
}

func (an *analyzer) callMeta(c *ast.CallExpr) callMeta {
	m := callMeta{}
	if len(c.Args) > 0 {
		m.firstArg = c.Args[0]
		if tv, ok := an.currentInfo.Types[c.Args[0]]; ok {
			m.firstType = tv.Type
		}
	}
	switch fun := c.Fun.(type) {
	case *ast.Ident:
		m.name = fun.Name
		if obj := an.currentInfo.Uses[fun]; obj != nil {
			if obj.Pkg() != nil {
				m.pkgPath = obj.Pkg().Path()
			}
		}
	case *ast.SelectorExpr:
		m.isSelector = true
		m.name = fun.Sel.Name
		if sel := an.currentInfo.Selections[fun]; sel != nil {
			m.recvType = sel.Recv()
			obj := sel.Obj()
			if obj != nil && obj.Pkg() != nil {
				m.pkgPath = obj.Pkg().Path()
			}
			if fn, ok := obj.(*types.Func); ok {
				m.fullName = fn.FullName()
				m.verbose = m.fullName
			}
		} else if obj := an.currentInfo.Uses[fun.Sel]; obj != nil {
			if obj.Pkg() != nil {
				m.pkgPath = obj.Pkg().Path()
			}
			if fn, ok := obj.(*types.Func); ok {
				m.fullName = fn.FullName()
				m.verbose = m.fullName
			}
		}
	}
	return m
}

func (an *analyzer) shouldIgnore(m callMeta) bool {
	if m.pkgPath != "" && an.cfg.ignorePkgs[m.pkgPath] {
		return true
	}
	if an.cfg.ignores.re != nil {
		if r := an.cfg.ignores.re[m.pkgPath]; r != nil && r.MatchString(m.name) {
			return true
		}
		if r := an.cfg.ignores.re[""]; r != nil && r.MatchString(m.name) {
			return true
		}
	}
	if m.fullName != "" {
		for _, r := range an.cfg.excludes {
			if r.name != m.fullName {
				continue
			}
			if r.argType == "" || an.firstArgMatches(r.argType, m.firstArg, m.firstType) {
				return true
			}
		}
	}
	if an.defaultHashWrite(m) {
		return true
	}
	return false
}

func (an *analyzer) defaultHashWrite(m callMeta) bool {
	if an.cfg.excludeOnly || m.name != "Write" || m.recvType == nil {
		return false
	}
	s := types.TypeString(m.recvType, qualifier)
	return s == "hash.Hash" || s == "hash.Hash32" || s == "hash.Hash64"
}

func (an *analyzer) firstArgMatches(want string, expr ast.Expr, typ types.Type) bool {
	if want == "" {
		return true
	}
	if expr == nil {
		return false
	}
	if want == "os.Stdout" || want == "os.Stderr" {
		if sel, ok := expr.(*ast.SelectorExpr); ok && sel.Sel.Name == strings.TrimPrefix(want, "os.") {
			if id, ok := sel.X.(*ast.Ident); ok && id.Name == "os" {
				return true
			}
		}
		return false
	}
	if typ == nil {
		return false
	}
	if b, ok := typ.(*types.Basic); ok && b.Info()&types.IsUntyped != 0 {
		typ = types.Default(typ)
	}
	return types.TypeString(typ, qualifier) == want
}

func qualifier(p *types.Package) string {
	if p == nil {
		return ""
	}
	return p.Path()
}

func (an *analyzer) addFinding(pos token.Pos, name string) {
	if pos == token.NoPos {
		return
	}
	p := an.fset.Position(pos)
	abs, err := filepath.Abs(p.Filename)
	if err == nil {
		abs = filepath.Clean(abs)
	} else {
		abs = filepath.Clean(p.Filename)
	}
	display := abs
	if !an.cfg.abspath {
		if rel, err := filepath.Rel(an.cfg.cwd, abs); err == nil {
			display = rel
		}
	}
	text := ""
	if sf := an.files[abs]; sf != nil {
		if p.Line >= 1 && p.Line <= len(sf.lines) {
			text = strings.TrimSpace(sf.lines[p.Line-1])
		}
	}
	an.findings = append(an.findings, finding{absFile: abs, file: filepath.ToSlash(display), line: p.Line, col: p.Column, text: text, name: name})
}

func dedupFindings(in []finding) []finding {
	seen := make(map[string]bool)
	out := make([]finding, 0, len(in))
	for _, f := range in {
		key := fmt.Sprintf("%s:%d:%d", f.absFile, f.line, f.col)
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, f)
	}
	return out
}
